/**
 * Official UQlearn Certificate Logo Asset
 * Embedded base64 Data URI from public/logo/logo.png for 100% offline SVG & canvas rendering.
 */
import { resolveBrandingLogoUrl } from './branding';

export const OFFICIAL_UQLEARN_LOGO_DATA_URI = 'data:image/png;base64,';
export const OFFICIAL_UQLEARN_LOGO_URL = OFFICIAL_UQLEARN_LOGO_DATA_URI;
export const UQLEARN_OFFICIAL_LOGO_DATA_URL = OFFICIAL_UQLEARN_LOGO_DATA_URI;

export function resolveCertificateLogo(customLogoUrl?: string | null): string {
  if (!customLogoUrl || typeof customLogoUrl !== 'string' || !customLogoUrl.trim()) {
    return OFFICIAL_UQLEARN_LOGO_DATA_URI;
  }

  const trimmed = customLogoUrl.trim();
  if (trimmed.startsWith('data:image/')) {
    return trimmed;
  }

  if (
    trimmed === '/logo/logo.png' ||
    trimmed === '/logo/logo.svg' ||
    trimmed.endsWith('/logo/logo.png') ||
    trimmed.endsWith('/logo/logo.svg') ||
    trimmed.includes('uqlearn.org/logo')
  ) {
    return OFFICIAL_UQLEARN_LOGO_DATA_URI;
  }

  return resolveBrandingLogoUrl(trimmed);
}

export function convertImageElementToDataUri(src: string): Promise<string> {
  if (!src || !src.trim()) return Promise.resolve(OFFICIAL_UQLEARN_LOGO_DATA_URI);
  if (src.startsWith('data:image/')) return Promise.resolve(src);

  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth || img.width || 240;
        canvas.height = img.naturalHeight || img.height || 240;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          const dataUri = canvas.toDataURL('image/png');
          if (dataUri && dataUri.startsWith('data:image/')) {
            resolve(dataUri);
            return;
          }
        }
      } catch (e) {
        console.warn('Canvas export tainting:', e);
      }
      resolve(OFFICIAL_UQLEARN_LOGO_DATA_URI);
    };
    img.onerror = () => resolve(OFFICIAL_UQLEARN_LOGO_DATA_URI);
    img.src = src;
  });
}

/**
 * Ensures any certificate logo URL is converted into a base64 Data URL
 * to avoid canvas tainting and missing images during SVG-to-Canvas exports.
 */
export async function convertImageUrlToDataUri(url?: string | null): Promise<string> {
  if (!url || !url.trim()) return OFFICIAL_UQLEARN_LOGO_DATA_URI;
  const trimmed = url.trim();
  if (trimmed.startsWith('data:image/')) return trimmed;

  if (
    trimmed === '/logo/logo.png' ||
    trimmed === '/logo/logo.svg' ||
    trimmed.endsWith('/logo/logo.png') ||
    trimmed.endsWith('/logo/logo.svg') ||
    trimmed.includes('uqlearn.org/logo')
  ) {
    return OFFICIAL_UQLEARN_LOGO_DATA_URI;
  }

  try {
    const canvasDataUri = await convertImageElementToDataUri(trimmed);
    if (canvasDataUri && canvasDataUri.startsWith('data:image/')) {
      return canvasDataUri;
    }
  } catch (e) {
    // fallback
  }

  return OFFICIAL_UQLEARN_LOGO_DATA_URI;
}
